CREATE TABLE ha_connections(id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,base_url text NOT NULL,credential_id uuid,enabled boolean NOT NULL DEFAULT true,last_sync timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,name));
CREATE TABLE ha_states(id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),connection_id uuid NOT NULL,entity_id text NOT NULL,state text NOT NULL DEFAULT '',attributes jsonb NOT NULL DEFAULT '{}',observed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,connection_id,entity_id));
CREATE INDEX ha_states_owner_conn ON ha_states(owner_id,connection_id);
CREATE TABLE github_connections(id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,credential_id uuid,enabled boolean NOT NULL DEFAULT true,last_sync timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,name));
CREATE TABLE github_events_cache(id uuid NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),connection_id uuid NOT NULL,repo text NOT NULL DEFAULT '',kind text NOT NULL,number integer,title text NOT NULL DEFAULT '',state text NOT NULL DEFAULT '',url text NOT NULL DEFAULT '',observed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,connection_id,kind,number));
CREATE INDEX github_events_owner_conn ON github_events_cache(owner_id,connection_id);
